window.HOEREN_TESTS[70] = {"id":"im-baumarkt","name":"Im Baumarkt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Willkommen im Baumarkt. Heute ist Aktionstag im Garten-Bereich. Alle Pflanzen sind 25 Prozent günstiger, auch die Gartenmöbel. Werkzeug ist heute leider nicht im Angebot, das bleibt zum normalen Preis. Die Aktion gilt nur bis 18 Uhr. Fragen Sie unsere Mitarbeiter im grünen Hemd. Viel Spaß beim Einkaufen!","gender":"f","q":"Was ist heute nicht im Angebot?","opts":["Das Werkzeug.","Die Pflanzen.","Die Gartenmöbel."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Du, ich streiche am Wochenende mein Wohnzimmer und brauche Hilfe. Ich war im Baumarkt und habe Farbe gekauft, aber keine Pinsel und keine Leiter. Hast du Pinsel? Und vielleicht eine Leiter? Ich habe nur eine kleine. Komm doch Samstag vorbei, ich koche danach. Ruf zurück!","gender":"m","q":"Was hat Markus im Baumarkt gekauft?","opts":["Pinsel.","Eine Leiter.","Farbe."],"correct":2},{"transcript":"Achtung Kunden: Unser Lieferservice ändert sich. Große Sachen wie Holz und Steine liefern wir jetzt schon am nächsten Tag, nicht erst nach einer Woche und nicht am selben Tag. Die Lieferung kostet 30 Euro. Ab 500 Euro Einkauf ist sie kostenlos. Bestellen Sie direkt an der Information. Vielen Dank!","gender":"m","q":"Wann kommt die Lieferung jetzt?","opts":["Nach einer Woche.","Am nächsten Tag.","Am selben Tag."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich baue ein Regal selbst und brauche Schrauben und einen Akkuschrauber. Im Baumarkt kann man Werkzeug leihen, wusstest du das? Möbel reparieren lassen oder Regale bestellen muss ich nicht. Leihen ist viel günstiger als kaufen. Kommst du mit, mir helfen? Sag Bescheid, danke dir!","gender":"f","q":"Was kann man im Baumarkt machen?","opts":["Werkzeug leihen.","Möbel reparieren lassen.","Regale bestellen."],"correct":0},{"transcript":"Liebe Kunden: Am Samstag bieten wir einen kostenlosen Kurs an. Sie lernen, wie man richtig fliest und Wände streicht, nicht Möbel bauen und nicht gärtnern. Der Kurs dauert zwei Stunden und beginnt um 10 Uhr. Bitte melden Sie sich vorher an der Information an, die Plätze sind begrenzt. Wir freuen uns auf Sie!","gender":"f","q":"Was lernt man im Kurs?","opts":["Möbel bauen.","Gärtnern.","Fliesen und streichen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Baumarkt hat heute einen Familientag und unsere Liste liegt im Auto."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du sie mitgebracht hast. Wir renovieren das Wohnzimmer und das Bad."},{"speaker":"Lukas","gender":"m","text":"Ich kaufe Farbe für die alten Wände. Ein Eimer Hellgrau reicht für zwei Zimmer."},{"speaker":"Lisa","gender":"f","text":"Für den Balkon nehme ich Pflanzen. Basilikum und eine Rose kommen in Kästen."},{"speaker":"Lukas","gender":"m","text":"Nehmen wir auch neue Tapeten für das Wohnzimmer mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Tapeten wollen wir nicht. Die Wände bleiben bei uns glatt."},{"speaker":"Lukas","gender":"m","text":"Tom repariert am Samstag das wacklige Regal im Flur."},{"speaker":"Lisa","gender":"f","text":"Tom sucht Werkzeug für das Regal. Ein Hammer und eine Zange fehlen noch im Kasten."},{"speaker":"Lukas","gender":"m","text":"Sara macht das kleine Bad in der Wohnung neu."},{"speaker":"Lisa","gender":"f","text":"Sara entscheidet sich für Fliesen. Helle Stücke zeigt der Prospekt auf dem Tisch."},{"speaker":"Lukas","gender":"m","text":"Kaufen wir Gartenmöbel für den Balkon dazu?"},{"speaker":"Lisa","gender":"f","text":"Nein. Gartenmöbel kaufen wir auch nicht. Die alten Stühle reichen noch."},{"speaker":"Lukas","gender":"m","text":"Tim sitzt abends zu dunkel im Sessel und kneift die Augen zusammen."},{"speaker":"Lisa","gender":"f","text":"Tim holt eine Lampe für den dunklen Sessel. Sie soll über dem Tisch ruhig leuchten."},{"speaker":"Lukas","gender":"m","text":"Dann holen wir uns vorn einen großen Wagen."},{"speaker":"Lisa","gender":"f","text":"Ich schiebe ihn schon langsam zum Eingang."}],"options":[{"letter":"a","text":"Holz"},{"letter":"b","text":"Schloss und Schlüssel"},{"letter":"c","text":"Fliesen"},{"letter":"d","text":"Pflanzen"},{"letter":"e","text":"Werkzeug"},{"letter":"f","text":"Farbe"},{"letter":"g","text":"Tapeten"},{"letter":"h","text":"Gartenmöbel"},{"letter":"i","text":"Lampe"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"e"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wo finde ich die Schrauben? Am Eingang vielleicht?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nicht am Eingang. In Gang 7, bei den Werkzeugen."},{"speaker":"Kunde","gender":"m","text":"Und die Farbe, auch Gang 7?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nein, die Farbe ist in Gang 12, ganz hinten. Schrauben Gang 7, Farbe Gang 12."},{"speaker":"Kunde","gender":"m","text":"Danke, dann gehe ich zuerst in Gang 7 zu den Schrauben."}],"q":"Wo sind die Schrauben?","opts":["Am Eingang.","In Gang 12.","In Gang 7."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, können Sie mir die Farbe mischen? Ich will kein dunkles Grün und kein Weiß."},{"speaker":"Mitarbeiterin","gender":"f","text":"Klar, welcher Farbton darf es sein? Dunkles Grün und Weiß haben wir fertig."},{"speaker":"Kundin","gender":"f","text":"Ein helles Blau bitte, für das Wohnzimmer."},{"speaker":"Mitarbeiterin","gender":"f","text":"Einen Moment, helles Blau mische ich jetzt. Das dauert fünf Minuten."},{"speaker":"Kundin","gender":"f","text":"Super, dann warte ich hier. Helles Blau ist perfekt. Danke."}],"q":"Welche Farbe möchte die Kundin?","opts":["Dunkles Grün.","Helles Blau.","Weiß."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, ich möchte einen Bohrer leihen. Kostet das 8 Euro oder 20 Euro?"},{"speaker":"Mitarbeiter","gender":"m","text":"Pro Tag kostet der Bohrer 12 Euro, nicht 8 Euro."},{"speaker":"Mann","gender":"m","text":"Und das Wochenende, zwei Tage?"},{"speaker":"Mitarbeiter","gender":"m","text":"Zwei Tage für 20 Euro. Also ein Tag 12, Wochenende 20, nicht 8 Euro."},{"speaker":"Mann","gender":"m","text":"Gut, dann leihe ich den Bohrer für einen Tag, 12 Euro. Danke."}],"q":"Was kostet der Bohrer pro Tag?","opts":["12 Euro.","20 Euro.","8 Euro."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, diese Lampe ist kaputt. Können Sie sie reparieren oder verkaufen Sie mir eine neue?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Reparieren tun wir nicht, und eine neue müssen Sie nicht kaufen. Haben Sie den Kassenbon?"},{"speaker":"Frau","gender":"f","text":"Ja, hier ist der Bon."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gut, dann tausche ich sie um. Sie bekommen eine neue Lampe, kostenlos."},{"speaker":"Frau","gender":"f","text":"Danke, der Umtausch ist super. Reparieren muss sie niemand."}],"q":"Was macht die Mitarbeiterin?","opts":["Sie repariert die Lampe.","Sie tauscht die Lampe um.","Sie verkauft eine neue."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, liefern Sie das Holz nach Hause? Heute Abend oder übermorgen?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Nicht heute Abend und nicht übermorgen. Ja, morgen Vormittag."},{"speaker":"Kunde","gender":"m","text":"Muss ich zu Hause sein?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, jemand muss da sein, morgen Vormittag zwischen 8 und 12 Uhr."},{"speaker":"Kunde","gender":"m","text":"Gut, morgen Vormittag bin ich da. Danke für die Lieferung."}],"q":"Wann kommt das Holz?","opts":["Heute Abend.","Übermorgen.","Morgen Vormittag."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Schulz, einem Baumarkt-Mitarbeiter. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Schulz, Sie arbeiten seit 12 Jahren im Baumarkt. Wer kommt zu Ihnen?"},{"speaker":"Schulz","gender":"m","text":"Ganz unterschiedliche Leute. Früher kamen vor allem Profis und Handwerker. Heute machen immer mehr Privatleute alles selbst — das nennt man Heimwerken. Sie wollen sparen und sind auch stolz, wenn sie etwas selbst geschafft haben. Das finde ich toll."},{"speaker":"Reporterin","gender":"f","text":"Was ist die häufigste Frage?"},{"speaker":"Schulz","gender":"m","text":"Wo etwas steht — der Baumarkt ist riesig, da verliert man leicht den Überblick. Und oft fragen die Leute, welches Werkzeug sie für ein Projekt brauchen. Da berate ich gern. Es macht Spaß, jemandem zu helfen, der etwas Neues ausprobiert."},{"speaker":"Reporterin","gender":"f","text":"Machen die Kunden oft Fehler?"},{"speaker":"Schulz","gender":"m","text":"Ja, leider. Viele kaufen zu wenig Material und müssen dann nochmal kommen. Oder sie unterschätzen, wie schwer eine Arbeit ist. Ich sage dann ehrlich: Manche Sachen sollte man besser einem Fachmann überlassen. Vor allem bei Strom und Wasser."},{"speaker":"Reporterin","gender":"f","text":"Was ist gerade besonders gefragt?"},{"speaker":"Schulz","gender":"m","text":"Alles für den Garten und den Balkon. Seit ein paar Jahren wollen die Leute es draußen schön haben. Auch das Thema Energiesparen ist groß — gute Fenster, Dämmung. Und immer mehr fragen nach umweltfreundlichen Farben und Materialien. Das freut mich."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie Heimwerkern?"},{"speaker":"Schulz","gender":"m","text":"Gut planen, bevor man kauft. Schreiben Sie eine Liste und messen Sie genau. Lieber etwas mehr Material kaufen als zu wenig. Und tragen Sie immer eine Schutzbrille und Handschuhe. Sicherheit ist wichtiger als Eile. Lieber langsam und richtig als schnell und gefährlich."}],"items":[{"q":"Herr Schulz rät, alle Arbeiten selbst zu machen, auch bei Strom.","correct":"nein"},{"q":"Heute machen immer mehr Privatleute selbst Heimwerker-Arbeiten.","correct":"ja"},{"q":"Viele Kunden kaufen zu wenig Material.","correct":"ja"},{"q":"Sachen für Garten und Balkon sind gerade besonders gefragt.","correct":"ja"},{"q":"Er findet Eile wichtiger als Sicherheit.","correct":"nein"}]}]};
